      8: [{ week: 8, keyword: "hoop", question: "In basketball, you try to throw the ball into the net or _______.", options: ["shot put", "hoop", "hurdle", "discus"], answer: "B", explanation: "hoop意为\"篮筐/呼啦圈\"" }, { week: 8, keyword: "hurdle", question: "A plastic fence you must jump over during a running race is a _______.", options: ["hoop", "pacing", "hurdle", "sprint"], answer: "C", explanation: "hurdle意为\"跨栏\"" }, { week: 8, keyword: "sprinting", question: "Running as fast as your legs can go for a short distance is _______.", options: ["pacing", "sprinting", "bouncing", "walking"], answer: "B", explanation: "sprinting意为\"冲刺/短跑\"" }],
      9: [{ week: 9, keyword: "bounce", question: "If you throw a ball hard at the floor, it will _______ back up.", options: ["shot put", "hurdle", "bounce", "sprint"], answer: "C", explanation: "bounce意为\"弹跳/拍球\"" }],
      10: [{ week: 10, keyword: "review", question: "What sport uses a heavy metal ball?", options: ["Pacing B) Sprinting C) Bounce D) The shot put"], answer: "D", explanation: "", passage: "In track and field, we run a long race and use good pacing so we are not tired. Next, we bounce a basketball on the court. Finally, we go to the throwing field and push a heavy metal ball far for the shot put." }],
      11: [{ week: 11, keyword: "practice", question: "To get better at any sport, you must _______ it every day.", options: ["practice", "sprint", "save", "bounce"], answer: "A", explanation: "practice意为\"练习\"" }, { week: 11, keyword: "discus", question: "A heavy, flat, round plate that you spin and throw far is the _______.", options: ["discus", "shot put", "lap", "hoop"], answer: "A", explanation: "discus指⽥径项⽬\"铁饼\"" }],
