      13: [{ week: 13, keyword: "medal", question: "A gold or silver prize you get around your neck for winning is a _______.", options: ["hurdle", "hoop", "save", "medal"], answer: "D", explanation: "medal意为\"奖牌\"" }, { week: 13, keyword: "down", question: "Doing slow stretches after a hard run to relax your body is the _______.", options: ["reaction time", "cool-down", "sprint", "pacing"], answer: "B", explanation: "cool-down意为\"整理运动/ 冷⾝活动\"" }],
      14: [{ week: 14, keyword: "medal", question: "The fastest runner proudly wore his first-place _______.", options: ["lap", "medal", "discus", "cool-down"], answer: "B", explanation: "巩固词汇：medal意为\"奖牌\"" }, { week: 14, keyword: "down", question: "Always take 5 minutes for a slow _______ so your muscles do not hurt tomorrow.", options: ["sprint", "relay", "cool-down", "save"], answer: "C", explanation: "巩固词汇：cool- down意为\"整理运动\"" }],
      15: [{ week: 15, keyword: "review", question: "What is a race where team partners pass a stick called?", options: ["A sprint B) A relay race C) A reaction time D) A cool-down"], answer: "B", explanation: "", passage: "We line up for the team relay race. We wait for the whistle. Our reaction time is very fast, so we start quickly! We sprint as fast as we can and pass the stick to our partner to win the race!" }],
